from itertools import product


def solve_three_coloring(instance):
    """Return True iff graph is 3-colourable. Brute force over 3^n colourings."""
    n = instance["n"]
    edges = instance["edges"]
    for colouring in product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if colouring[u] == colouring[v]:
                ok = False
                break
        if ok:
            return True
    return False


def solve_sat_bruteforce(instance):
    """Return True iff CNF is satisfiable. Brute force over 2^m assignments."""
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in product((False, True), repeat=m):
        sat = True
        for clause in clauses:
            if not any((bits[abs(lit) - 1] if lit > 0 else not bits[abs(lit) - 1])
                       for lit in clause):
                sat = False
                break
        if sat:
            return True
    return False


def solve_sat(instance):
    """DPLL SAT solver (exact). Returns True iff satisfiable."""
    m = instance["num_vars"]
    clauses = [tuple(dict.fromkeys(c)) for c in instance["clauses"]]

    def dpll(clauses, assignment):
        # Simplify clauses under current assignment.
        simplified = []
        for clause in clauses:
            new_clause = []
            satisfied = False
            for lit in clause:
                var = abs(lit)
                if var in assignment:
                    val = assignment[var]
                    if (lit > 0) == val:
                        satisfied = True
                        break
                else:
                    new_clause.append(lit)
            if satisfied:
                continue
            if not new_clause:
                return False  # empty clause -> conflict
            simplified.append(tuple(new_clause))
        if not simplified:
            return True  # all clauses satisfied
        # Unit propagation.
        unit = None
        for clause in simplified:
            if len(clause) == 1:
                unit = clause[0]
                break
        if unit is not None:
            var = abs(unit)
            new_assignment = dict(assignment)
            new_assignment[var] = unit > 0
            return dpll(simplified, new_assignment)
        # Pure literal elimination.
        signs = {}
        for clause in simplified:
            for lit in clause:
                var = abs(lit)
                signs.setdefault(var, set()).add(lit > 0)
        pure = None
        for var, s in signs.items():
            if len(s) == 1:
                pure = (var, next(iter(s)))
                break
        if pure is not None:
            var, val = pure
            new_assignment = dict(assignment)
            new_assignment[var] = val
            return dpll(simplified, new_assignment)
        # Branch on the first literal's variable.
        var = abs(simplified[0][0])
        for val in (True, False):
            new_assignment = dict(assignment)
            new_assignment[var] = val
            if dpll(simplified, new_assignment):
                return True
        return False

    return dpll(clauses, {})
