def solve_three_coloring_fast(instance):
    """Backtracking 3-colourability (exact)."""
    n = instance["n"]
    adj = [[] for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].append(v)
        adj[v].append(u)
    colour = [-1] * n

    def bt(v):
        if v == n:
            return True
        for c in range(3):
            if all(colour[w] != c for w in adj[v]):
                colour[v] = c
                if bt(v + 1):
                    return True
                colour[v] = -1
        return False

    return bt(0)
